@startuml

class Hospital {}

class Office {}

abstract class User {}

class Doctor extends User {}

class Patient extends User {
  + CreateAppointment()
}

class Schedule {}

class Appointment {
  + date : date
  + startTime : time
  + endTime : time
  + type : string
}

Hospital "1" *-- "*" Office

Doctor "1..*" -- "*" Office : applies to practice in

Doctor "1" -- "*" Schedule : creates

Office "1" -- "*" Schedule : has

Patient "1" -- "*" Appointment : books

Doctor "1" -- "*" Appointment : has

Schedule "1" -- "*" Appointment : for

@enduml

